import type { VercelRequest, VercelResponse } from '@vercel/node'
import { getTweet } from 'react-tweet/api'

const handler = async (req: VercelRequest, res: VercelResponse) => {
  const tweetId = req.query.tweet

  if (req.method !== 'GET' || typeof tweetId !== 'string') {
    res.status(400).json({ error: 'Bad Request.' })
    return
  }

  try {
    const tweet = await getTweet(tweetId)
    res.status(tweet ? 200 : 404).json({ data: tweet ?? null })
  } catch (error) {
    console.error(error)
    res.status(400).json({ error: error.message ?? 'Bad request.' })
  }
}

export default handler

import type { Tweet } from './types/index.js'

const SYNDICATION_URL = 'https://cdn.syndication.twimg.com'

export class TwitterApiError extends Error {
  status: number
  data: any

  constructor({
    message,
    status,
    data,
  }: {
    message: string
    status: number
    data: any
  }) {
    super(message)
    this.name = 'TwitterApiError'
    this.status = status
    this.data = data
  }
}

const TWEET_ID = /^[0-9]+$/

function getToken(id: string) {
  return ((Number(id) / 1e15) * Math.PI)
    .toString(6 ** 2)
    .replace(/(0+|\.)/g, '')
}

/**
 * Fetches a tweet from the Twitter syndication API.
 */
export async function fetchTweet(
  id: string,
  fetchOptions?: RequestInit
): Promise<{ data?: Tweet; tombstone?: true; notFound?: true }> {
  if (id.length > 40 || !TWEET_ID.test(id)) {
    throw new Error(`Invalid tweet id: ${id}`)
  }

  const url = new URL(`${SYNDICATION_URL}/tweet-result`)

  url.searchParams.set('id', id)
  url.searchParams.set('lang', 'en')
  url.searchParams.set(
    'features',
    [
      'tfw_timeline_list:',
      'tfw_follower_count_sunset:true',
      'tfw_tweet_edit_backend:on',
      'tfw_refsrc_session:on',
      'tfw_fosnr_soft_interventions_enabled:on',
      'tfw_show_birdwatch_pivots_enabled:on',
      'tfw_show_business_verified_badge:on',
      'tfw_duplicate_scribes_to_settings:on',
      'tfw_use_profile_image_shape_enabled:on',
      'tfw_show_blue_verified_badge:on',
      'tfw_legacy_timeline_sunset:true',
      'tfw_show_gov_verified_badge:on',
      'tfw_show_business_affiliate_badge:on',
      'tfw_tweet_edit_frontend:on',
    ].join(';')
  )
  url.searchParams.set('token', getToken(id))

  const res = await fetch(url.toString(), fetchOptions)
  const isJson = res.headers.get('content-type')?.includes('application/json')
  const data = isJson ? await res.json() : undefined

  if (res.ok) {
    if (data?.__typename === 'TweetTombstone') {
      return { tombstone: true }
    }
    if (data && Object.keys(data).length === 0) {
      return { notFound: true }
    }
    return { data }
  }
  if (res.status === 404) {
    return { notFound: true }
  }

  throw new TwitterApiError({
    message:
      typeof data.error === 'string'
        ? data.error
        : `Failed to fetch tweet at "${url}" with "${res.status}".`,
    status: res.status,
    data,
  })
}

import { fetchTweet } from './fetch-tweet.js'
import type { Tweet } from './types/index.js'

/**
 * Returns a tweet from the Twitter syndication API.
 */
export async function getTweet(
  id: string,
  fetchOptions?: RequestInit
): Promise<Tweet | undefined> {
  const { data, tombstone, notFound } = await fetchTweet(id, fetchOptions)

  if (notFound) {
    console.error(
      `The tweet ${id} does not exist or has been deleted by the account owner. Update your code to remove this tweet when possible.`
    )
  } else if (tombstone) {
    console.error(
      `The tweet ${id} has been made private by the account owner. Update your code to remove this tweet when possible.`
    )
  }

  return data
}

export async function getOEmbed(url: string): Promise<any> {
  const res = await fetch(`https://publish.twitter.com/oembed?url=${url}`)

  if (res.ok) return res.json()
  if (res.status === 404) return

  throw new Error(`Fetch for embedded tweet failed with code: ${res.status}`)
}

